import { z } from 'zod';
import { DomainError, notImplemented, type UseCase, type UseCaseContext } from '@agentic-ddd/core';
import { AgentUseCase } from '@agentic-ddd/decorators';
import { TaskCompleted } from '../domain/task.events';
import type { TaskRepository } from '../domain/task.repository';

export const completeTaskInput = z.object({ task_id: z.string().min(1) });
export const completeTaskOutput = z.object({ task_id: z.string(), status: z.literal('completed') });
export type CompleteTaskInput = z.infer<typeof completeTaskInput>;
export type CompleteTaskOutput = z.infer<typeof completeTaskOutput>;

@AgentUseCase({ name: 'complete_task', description: 'Carrega, conclui, salva e publica a tarefa; id ausente falha com TASK_NOT_FOUND.', whenToUse: 'Quando o usuário terminou uma tarefa.', whenNotToUse: 'Para criar uma nova tarefa.', input: completeTaskInput, output: completeTaskOutput, uses: ['method:Task.complete'], emits: [TaskCompleted] })
export class CompleteTask implements UseCase<CompleteTaskInput, CompleteTaskOutput> {
  constructor(private readonly tasks: TaskRepository) {}
  async execute(input: CompleteTaskInput, ctx: UseCaseContext): Promise<CompleteTaskOutput> {
    const task = await this.tasks.findById(input.task_id);
    if (!task) throw new DomainError('TASK_NOT_FOUND', 'A tarefa não foi encontrada.');
    task.complete();
    await this.tasks.save(task);
    await ctx.publish(task.pullEvents());
    return { task_id: task.id, status: 'completed' };








  }
}

import { expect, test } from 'bun:test';
import { DomainError, type UseCaseContext } from '@agentic-ddd/core';
import { covers, createTestContext } from '@agentic-ddd/testing';
import { CompleteTask } from '../application/complete-task';
import { Task } from '../domain/task';
import { TaskCompleted } from '../domain/task.events';
import type { TaskRepository } from '../domain/task.repository';
import { InMemoryTaskRepository } from '../infrastructure/in-memory-task.repository';

async function setup() {
  const task = Task.create('t1', 'Concluir tarefa');
  task.pullEvents();
  const storage = new InMemoryTaskRepository();
  await storage.save(task);
  const calls: string[] = [];
  const savedStatuses: string[] = [];
  const repository: TaskRepository = {
    async findById(id) {
      calls.push(`load:${id}`);
      return storage.findById(id);
    },
    async save(aggregate) {
      await storage.save(aggregate);
      savedStatuses.push(aggregate.status);
      calls.push(`save:${aggregate.id}`);
    },
  };
  const ctx = createTestContext({ correlationId: 'correlation-1', causationId: 'causation-1' });
  return { task, storage, calls, savedStatuses, repository, ctx };
}

test(covers([
  'usecase:complete_task',
  'criterion:0001/persistencia-conclusao',
], 'carrega t1, salva completed e aguarda a publicação de TaskCompleted pelo contexto'), async () => {
  const fixture = await setup();
  const ctx: UseCaseContext = {
    ...fixture.ctx,
    async publish(events) {
      expect(fixture.savedStatuses).toEqual(['completed']);
      expect((await fixture.storage.findById('t1'))?.status).toBe('completed');
      expect(events).toHaveLength(1);
      expect(events[0]?.correlationId).toBeNull();
      expect(events[0]?.causationId).toBeNull();
      await fixture.ctx.publish(events);
      fixture.calls.push('publish');
    },
  };

  const output = await new CompleteTask(fixture.repository).execute({ task_id: 't1' }, ctx);

  expect(output).toEqual({ task_id: 't1', status: 'completed' });
  expect(fixture.calls).toEqual(['load:t1', 'save:t1', 'publish']);
  expect(fixture.ctx.published).toHaveLength(1);
  expect(fixture.ctx.published[0]).toBeInstanceOf(TaskCompleted);
  expect(fixture.ctx.published[0]?.payload).toEqual({ taskId: 't1' });
  expect(fixture.ctx.published[0]?.correlationId).toBe(ctx.correlationId);
  expect(fixture.ctx.published[0]?.causationId).toBe(ctx.causationId);
  expect(fixture.task.pullEvents()).toEqual([]);
});

test(covers([
  'usecase:complete_task',
  'criterion:0001/persistencia-conclusao',
], 'rejeita id inexistente com TASK_NOT_FOUND sem salvar ou publicar'), async () => {
  const fixture = await setup();
  const execution = new CompleteTask(fixture.repository).execute({ task_id: 'missing' }, fixture.ctx);

  await expect(execution).rejects.toBeInstanceOf(DomainError);
  await expect(execution).rejects.toHaveProperty('code', 'TASK_NOT_FOUND');
  expect(fixture.calls).toEqual(['load:missing']);
  expect(fixture.savedStatuses).toEqual([]);
  expect(fixture.ctx.published).toEqual([]);
  expect(fixture.task.status).toBe('pending');
});

test(covers([
  'usecase:complete_task',
], 'rejeita segunda conclusão com TASK_ALREADY_COMPLETED sem nova gravação ou publicação'), async () => {
  const fixture = await setup();
  const useCase = new CompleteTask(fixture.repository);
  await useCase.execute({ task_id: 't1' }, fixture.ctx);
  fixture.calls.length = 0;

  const execution = useCase.execute({ task_id: 't1' }, fixture.ctx);

  await expect(execution).rejects.toBeInstanceOf(DomainError);
  await expect(execution).rejects.toHaveProperty('code', 'TASK_ALREADY_COMPLETED');
  expect(fixture.calls).toEqual(['load:t1']);
  expect(fixture.savedStatuses).toEqual(['completed']);
  expect(fixture.ctx.published).toHaveLength(1);
  expect(fixture.task.status).toBe('completed');
  expect(fixture.task.pullEvents()).toEqual([]);
});

test(covers([
  'usecase:complete_task',
], 'propaga falha ao salvar sem publicar ou retirar os eventos pendentes'), async () => {
  const fixture = await setup();
  const failure = new Error('Falha de persistência');
  const repository: TaskRepository = {
    findById: fixture.repository.findById,
    async save() {
      await Promise.resolve();
      throw failure;
    },
  };

  await expect(new CompleteTask(repository).execute({ task_id: 't1' }, fixture.ctx)).rejects.toBe(failure);

  expect(fixture.calls).toEqual(['load:t1']);
  expect(fixture.ctx.published).toEqual([]);
  expect(fixture.task.pullEvents()[0]).toBeInstanceOf(TaskCompleted);
});
